import{_ as l,a0 as o,w as d,s as p,I as s,x as e,a1 as i,A as n,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"用 Linux 的 at 命令来安排一个任务 | LCTT x X-CMD","titleTemplate":false,"description":"用 Linux 的 at 命令来安排一个任务 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Linux 的 at 命令来安排一个任务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Linux 的 at 命令来安排一个任务 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210815 Schedule a task with the Linux at command","title":"用 Linux 的 at 命令来安排一个任务","tag":"202108","desc":""},"relativePath":"202108/20210815 Schedule a task with the Linux at command.md","filePath":"[post].md"}'),h={name:"202108/20210815 Schedule a task with the Linux at command.md"};function r(u,a,g,k,b,m){const t=o("Link");return d(),p("div",null,[a[18]||(a[18]=s("h1",{id:"用-linux-的-at-命令来安排一个任务",tabindex:"-1"},[e("用 Linux 的 at 命令来安排一个任务 "),s("a",{class:"header-anchor",href:"#用-linux-的-at-命令来安排一个任务","aria-label":"Permalink to “用 Linux 的 at 命令来安排一个任务”"},"​")],-1)),a[19]||(a[19]=s("blockquote",null,[s("p",null,"at 命令是一种在特定时间和日期安排一次性任务的 Linux 终端方法。")],-1)),a[20]||(a[20]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/23/144542rmmyzwxsnanm4wpj.jpg",alt:""})],-1)),s("p",null,[a[1]||(a[1]=e("计算机擅长 ",-1)),i(t,{href:"https://opensource.com/article/20/11/orchestration-vs-automation"},{default:n(()=>[...a[0]||(a[0]=[e("自动化",-1)])]),_:1}),a[2]||(a[2]=e("，但不是每个人都知道如何使自动化工作。不过，能够在特定的时间为电脑安排一个任务，然后忘记它，这确实是一种享受。也许你有一个文件要在特定的时间上传或下载，或者你需要处理一批还不存在但可以保证在某个时间存在的文件，或者需要监控设置，或者你只是需要一个友好的提醒，在下班回家的路上买上面包和黄油。",-1))]),a[21]||(a[21]=c(`<p>这就是 <code>at</code> 命令的用处。</p><h3 id="什么是-linux-at-命令" tabindex="-1">什么是 Linux at 命令？ <a class="header-anchor" href="#什么是-linux-at-命令" aria-label="Permalink to “什么是 Linux at 命令？”">​</a></h3><p><code>at</code> 命令是在 Linux 终端让你在特定时间和日期安排一次性工作的方法。它是一种自发的自动化，在终端上很容易实现。</p><h3 id="安装-at" tabindex="-1">安装 at <a class="header-anchor" href="#安装-at" aria-label="Permalink to “安装 at”">​</a></h3><p>在 Linux 上，<code>at</code> 命令可能已经安装了。你可以使用 <code>at -V</code> 命令来验证它是否已经安装。只要返回一个版本号，就说明你已经安装了 <code>at</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at -V</span></span>
<span class="line"><span>at version x.y.z</span></span></code></pre></div><p>如果你试图使用 <code>at</code>，但没有找到该命令，大多数现代的 Linux 发行版会为你提供缺少的 <code>at</code> 软件包。</p><p>你可能还需要启动 <code>at</code> 守护程序，称为 <code>atd</code>。在大多数 Linux 系统中，你可以使用 <code>systemctl</code> 命令来启用该服务，并将它们设置为从现在开始自动启动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now atd</span></span></code></pre></div><h3 id="用-at-交互式地安排一个作业" tabindex="-1">用 at 交互式地安排一个作业 <a class="header-anchor" href="#用-at-交互式地安排一个作业" aria-label="Permalink to “用 at 交互式地安排一个作业”">​</a></h3><p>当你使用 <code>at</code> 命令并加上你希望任务运行的时间，会打开一个交互式 <code>at</code> 提示符。你可以输入你想在指定时间运行的命令。</p><p>做个比喻，你可以把这个过程看作是一个日历应用，就像你在你的手机上使用的那样。首先，你在某一天的某个时间创建一个事件，然后指定你想要发生什么。</p><p>例如，可以试试创建一个未来几分钟的任务，来给自己计划一个备忘录。这里运行一个简单的任务，以减少失败的可能性。要退出 <code>at</code> 提示符，请按键盘上的 <code>Ctrl+D</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at 11:20 AM</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; echo &quot;hello world&quot; &gt; ~/at-test.txt</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span>
<span class="line"><span>job 3 at Mon Jul 26 11:20:00 2021</span></span></code></pre></div><p>正如你所看到的，<code>at</code> 使用直观和自然的时间定义。你不需要用 24 小时制的时钟，也不需要把时间翻译成 UTC 或特定的 ISO 格式。一般来说，你可以使用你自然想到的任何符号，如 <code>noon</code>、<code>1:30 PM</code>、<code>13:37</code> 等等，来描述你希望一个任务发生的时间。</p><p>等待几分钟，然后在你创建的文件上运行 <code>cat</code> 或者 <code>tac</code> 命令，验证你的任务是否已经运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/at-test.txt</span></span>
<span class="line"><span>hello world</span></span></code></pre></div><h3 id="用-at-安排一个任务" tabindex="-1">用 at 安排一个任务 <a class="header-anchor" href="#用-at-安排一个任务" aria-label="Permalink to “用 at 安排一个任务”">​</a></h3><p>你不必使用 <code>at</code> 交互式提示符来安排任务。你可以使用 <code>echo</code> 或 <code>printf</code> 向它传送命令。在这个例子中，我使用了 <code>now</code> 符号，以及我希望任务从现在开始延迟多少分钟：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;echo &#39;hello again&#39; &gt;&gt; ~/at-test.txt&quot; | at now +1 minute</span></span></code></pre></div><p>一分钟后，验证新的命令是否已被执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/at-test.txt</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>hello again</span></span></code></pre></div><h3 id="时间表达式" tabindex="-1">时间表达式 <a class="header-anchor" href="#时间表达式" aria-label="Permalink to “时间表达式”">​</a></h3><p><code>at</code> 命令在解释时间时是非常宽容的。你可以在许多格式中选择，这取决于哪一种对你来说最方便：</p><ul><li><code>YYMMDDhhmm[.ss]</code>（两位的年份、月、日、小时、分钟，及可选的秒）</li><li><code>CCYYMMDDhhmm[.ss]</code>（四位的年份、月、日、时、分钟，及可选的秒）</li><li><code>now</code>（现在）</li><li><code>midnight</code>（午夜 00:00）</li><li><code>noon</code>（中午 12:00）</li><li><code>teatime</code>（下午 16 点）</li><li><code>AM</code>（上午）</li><li><code>PM</code>（下午）</li></ul><p>时间和日期可以是绝对时间，也可以加一个加号（<code>+</code>），使其与 <code>now</code> 相对。当指定相对时间时，你可以使用你可能用过的词语：</p><ul><li><code>minutes</code>（分钟）</li><li><code>hours</code>（小时）</li><li><code>days</code>（天）</li><li><code>weeks</code>（星期）</li><li><code>months</code>（月）</li><li><code>years</code>（年）</li></ul><h3 id="时间和日期语法" tabindex="-1">时间和日期语法 <a class="header-anchor" href="#时间和日期语法" aria-label="Permalink to “时间和日期语法”">​</a></h3><p><code>at</code> 命令对时间的输入相比日期不那么宽容。时间必须放在第一位，接着是日期，尽管日期默认为当前日期，并且只有在为未来某天安排任务时才需要。</p><p>这些是一些有效表达式的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;rsync -av /home/tux me@myserver:/home/tux/&quot; | at 3:30 AM tomorrow</span></span>
<span class="line"><span>$ echo &quot;/opt/batch.sh ~/Pictures&quot; | at 3:30 AM 08/01/2022</span></span>
<span class="line"><span>$ echo &quot;echo hello&quot; | at now + 3 days</span></span></code></pre></div><h3 id="查看你的-at-队列" tabindex="-1">查看你的 at 队列 <a class="header-anchor" href="#查看你的-at-队列" aria-label="Permalink to “查看你的 at 队列”">​</a></h3><p>当你爱上了 <code>at</code>，并且正在安排任务，而不是在桌子上的废纸上乱写乱画，你可能想查看一下你是否有任务还在队列中。</p><p>要查看你的 <code>at</code> 队列，使用 <code>atq</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ atq</span></span>
<span class="line"><span>10 Thu Jul 29 12:19:00 2021 a tux</span></span>
<span class="line"><span>9 Tue Jul 27 03:30:00 2021 a tux</span></span>
<span class="line"><span>7 Tue Jul 27 00:00:00 2021 a tux</span></span></code></pre></div><p>要从队列中删除一个任务，使用 <code>atrm</code> 命令和任务号。例如，要删除任务 7：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ atrm 7</span></span>
<span class="line"><span>$ atq</span></span>
<span class="line"><span>10 Thu Jul 29 12:19:00 2021 a tux</span></span>
<span class="line"><span>9 Tue Jul 27 03:30:00 2021 a tux</span></span></code></pre></div><p>要看一个计划中的任务的实际内容，你需要查看 <code>/var/spool/at</code> 下的内容。只有 root 用户可以查看该目录的内容，所以你必须使用 <code>sudo</code> 来查看或 <code>cat</code> 任何任务的内容。</p><h3 id="用-linux-at-安排任务" tabindex="-1">用 Linux at 安排任务 <a class="header-anchor" href="#用-linux-at-安排任务" aria-label="Permalink to “用 Linux at 安排任务”">​</a></h3><p><code>at</code> 系统是一个很好的方法，可以避免忘记在一天中晚些时候运行一个作业，或者在你离开时让你的计算机为你运行一个作业。与 <code>cron</code> 不同的是，它不像 <code>cron</code> 那样要求任务必须从现在起一直按计划运行到永远，因此它的语法比 <code>cron</code> 简单得多。</p><p>等下次你有一个希望你的计算机记住并管理它的小任务，试试 <code>at</code> 命令。</p><hr>`,42)),s("p",null,[a[4]||(a[4]=e("via: ",-1)),i(t,{href:"https://opensource.com/article/21/8/linux-at-command"},{default:n(()=>[...a[3]||(a[3]=[e("https://opensource.com/article/21/8/linux-at-command",-1)])]),_:1})]),s("p",null,[a[9]||(a[9]=e("作者：",-1)),i(t,{href:"https://opensource.com/users/seth"},{default:n(()=>[...a[5]||(a[5]=[e("Seth Kenlon",-1)])]),_:1}),a[10]||(a[10]=e(" 选题：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[6]||(a[6]=[e("lujun9972",-1)])]),_:1}),a[11]||(a[11]=e(" 译者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:n(()=>[...a[7]||(a[7]=[e("geekpi",-1)])]),_:1}),a[12]||(a[12]=e(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:n(()=>[...a[8]||(a[8]=[e("wxy",-1)])]),_:1})]),s("p",null,[a[15]||(a[15]=e("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[13]||(a[13]=[e("LCTT",-1)])]),_:1}),a[16]||(a[16]=e(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:n(()=>[...a[14]||(a[14]=[e("Linux中国",-1)])]),_:1}),a[17]||(a[17]=e(" 荣誉推出",-1))])])}const C=l(h,[["render",r]]);export{y as __pageData,C as default};
